=\frac{1}{B}\nabla f(w),
\]
because $\sum_{b}U_{b}\nabla_{b}f(w)=\nabla f(w)$. \qedhere
\end{proof}

\begin{lemma}[Gradient–Descent Relation]\label{lem:gdrel}
For any $w$ and any stepsize $\eta>0$,
\[
\E_{i}\!\bigl[f(w-\eta U_{i}\nabla_{i}f(w))\bigr]
\le f(w)-\frac{\eta}{2B}\,\norm{\nabla f(w)}^{2},
\qquad\text{provided }\;\eta L_{\max}\le 1 .
\tag{7}
\]
\end{lemma}
\begin{proof}
Apply Lemma \ref{lem:descent} with $h=-\eta\nabla_{i}f(w)$:
\[
f\!\bigl(w-\eta U_{i}\nabla_{i}f(w)\bigr)
\le f(w)-\eta\norm{\nabla_{i}f(w)}^{2}
+\frac{L_{i}\eta^{2}}{2}\norm{\nabla_{i}f(w)}^{2}.
\]
Taking expectation over $i$ and using (9)–(10) (see Step 1 below) yields
\[
\E_{i}[f(\cdot)]\le f(w)-\frac{\eta}{B}\norm{\nabla f(w)}^{2}
+\frac{\eta^{2}L_{\max}}{2B}\norm{\nabla f(w)}^{2}.
\]
If $\eta L_{\max}\le 1$, then $\frac{\eta^{2}L_{\max}}{2B}\le\frac{\eta}{2B}$,
which gives the claimed inequality. \qedhere
\end{proof}

\section*{Main Proof (Step‑by‑Step Derivation)}
We prove Theorem \ref{thm:main}. Throughout the proof we denote
$\mathcal{F}_{t}$ the $\sigma$‑algebra generated by the random indices
$\{i_{0},\dots ,i_{t-1}\}$.

\subsection*{Step 1 – One‑Step Expected Decrease}
From the descent lemma (Lemma \ref{lem:descent}) with $h=-\eta\nabla_{i_{t}}f(w^{t})$ we have
\[
f\!\left(w^{t+1}\right)
\le f\!\left(w^{t}\right)
-\eta\bigl\langle\nabla_{i_{t}}f(w^{t}),\nabla_{i_{t}}f(w^{t})\bigr\rangle
+\frac{L_{i_{t}}}{2}\eta^{2}\norm{\nabla_{i_{t}}f(w^{t})}^{2}.
\tag{8}
\]
Taking conditional expectation w.r.t.\ $\mathcal{F}_{t}$ and using that $i_{t}$ is
independent of $\mathcal{F}_{t}$ yields
\[
\E\!\bigl[f(w^{t+1})\mid\mathcal{F}_{t}\bigr]
\le f(w^{t})
-\eta\,\E\!\bigl[\norm{\nabla_{i_{t}}f(w^{t})}^{2}\mid\mathcal{F}_{t}\bigr]
+\frac{\eta^{2}}{2}\E\!\bigl[L_{i_{t}}\norm{\nabla_{i_{t}}f(w^{t})}^{2}\mid\mathcal{F}_{t}\bigr].
\tag{9}
\]

\textbf{[Step 1]} The two expectations on the right–hand side can be written explicitly:
\[
\E\!\bigl[\norm{\nabla_{i_{t}}f(w^{t})}^{2}\mid\mathcal{F}_{t}\bigr]
=\frac{1}{B}\sum_{b=1}^{B}\norm{\nabla_{b}f(w^{t})}^{2},
\tag{10}
\]
\[
\E\!\bigl[L_{i_{t}}\norm{\nabla_{i_{t}}f(w^{t})}^{2}\mid\mathcal{F}_{t}\bigr]
=\frac{1}{B}\sum_{b=1}^{B}L_{b}\norm{\nabla_{b}f(w^{t})}^{2}
\le L_{\max}\,\frac{1}{B}\sum_{b=1}^{B}\norm{\nabla_{b}f(w^{t})}^{2}.
\tag{11}
\]

\subsection*{Step 2 – Relate Block Norm to Full Gradient Norm}
Because the blocks are orthogonal,
\[
\norm{\nabla f(w)}^{2}
=\sum_{b=1}^{B}\norm{\nabla_{b}f(w)}^{2}.
\tag{12}
\]
\textbf{[Step 2]} Substituting (10)–(12) into (9) gives
\[
\E\!\bigl[f(w^{t+1})\mid\mathcal{F}_{t}\bigr]
\le f(w^{t})-\frac{\eta}{B}\norm{\nabla f(w^{t})}^{2}
+\frac{\eta^{2}L_{\max}}{2B}\norm{\nabla f(w^{t})}^{2}.
\tag{13}
\]

\subsection*{Step 3 – Choose Stepsize and Verify the Key Inequality}
% CORRECTED: the true relation is $L_{\max}\le B\bar L$, not $\bar L\le L_{\max}$.
Since $L_{\max}\le B\bar L$, the stepsize (3) satisfies
\[
\eta L_{\max}
=\frac{L_{\max}}{B\bar L}
\le 1 .
\tag{14}
\]
% CORRECTED: from $\eta L_{\max}\le1$ we obtain
\[
\frac{\eta}{B}-\frac{\eta^{2}L_{\max}}{2B}
\;\ge\;\frac{\eta}{2B}.
\tag{15}
\]
\textbf{[Step 3]} Plugging (15) into (13) yields the clean descent inequality
\[
\E\!\bigl[f(w^{t+1})\mid\mathcal{F}_{t}\bigr]
\le f(w^{t})-\frac{\eta}{2B}\norm{\nabla f(w^{t})}^{2}.
\tag{16}
\]

\subsection*{Step 4 – From Gradient Norm to Function Suboptimality}
Convexity of $f$ implies for any $w^{*}\in\arg\min f$,
\[
f(w^{t})-f(w^{*})\le\langle\nabla f(w^{t}),\,w^{t}-w^{*}\rangle
\le\norm{\nabla f(w^{t})}\norm{w^{t}-w^{*}}.
\tag{17}
\]
Thus,
\[
\norm{\nabla f(w^{t})}^{2}
\ge\frac{\bigl(f(w^{t})-f(w^{*})\bigr)^{2}}{\norm{w^{t}-w^{*}}^{2}}.
\tag{18}
\]

\subsection*{Step 5 – Recursion on the Distance to Optimum}
Consider the squared distance after the update.
Using (1) and expanding the norm we obtain
\[
\begin{aligned}
\norm{w^{t+1}-w^{*}}^{2}
&=\norm{w^{t}-w^{*}}^{2}
-2\eta\langle U_{i_{t}}\nabla_{i_{t}}f(w^{t}),\,w^{t}-w^{*}\rangle
+\eta^{2}\norm{U_{i_{t}}\nabla_{i_{t}}f(w^{t})}^{2}\\
&=\norm{w^{t}-w^{*}}^{2}
-2\eta\langle \nabla_{i_{t}}f(w^{t}),\,w^{(i_{t}),t}-w^{(i_{t}),*}\rangle
+\eta^{2}\norm{\nabla_{i_{t}}f(w^{t})}^{2}.
\end{aligned}
\tag{19}
\]
% CORRECTED: expectation of the last term does **not** involve $L_{\max}$.
Taking expectation conditional on $\mathcal{F}_{t}$ and using Lemma \ref{lem:unbiased} gives
\[
\begin{aligned}
\E\!\bigl[\norm{w^{t+1}-w^{*}}^{2}\mid\mathcal{F}_{t}\bigr]
\le &\;\norm{w^{t}-w^{*}}^{2}
-\frac{2\eta}{B}\bigl[f(w^{t})-f(w^{*})\bigr]
+\frac{\eta^{2}}{B}\norm{\nabla f(w^{t})}^{2}.
\end{aligned}
\tag{20}
\]
\textbf{[Step 5]} Apply inequality (15) to bound the last term:
\[
\frac{\eta^{2}}{B}\norm{\nabla f(w^{t})}^{2}
\le\frac{\eta}{2B}\norm{\nabla f(w^{t})}^{2}.
\tag{21}
\]
Now invoke Lemma \ref{lem:gdrel} (or equivalently (16)) to replace the
gradient‑norm term:
\[
\frac{\eta}{2B}\norm{\nabla f(w^{t})}^{2}
\le f(w^{t})-\E\!\bigl[f(w^{t+1})\mid\mathcal{F}_{t}\bigr].
\tag{22}
\]
Substituting (22) into (20) yields
\[
\E\!\bigl[\norm{w^{t+1}-w^{*}}^{2}\mid\mathcal{F}_{t}\bigr]
\le \norm{w^{t}-w^{*}}^{2}
-\frac{2\eta}{B}\bigl[f(w^{t})-f(w^{*})\bigr]
+f(w^{t})-\E\!\bigl[f(w^{t+1})\mid\mathcal{F}_{t}\bigr].
\tag{23}
\]
Rearranging,
\[
\E\!\bigl[\norm{w^{t+1}-w^{*}}^{2}\mid\mathcal{F}_{t}\bigr]
+\frac{2\eta}{B}\E\!\bigl[f(w^{t+1})\mid\mathcal{F}_{t}\bigr]
\le \norm{w^{t}-w^{*}}^{2}
+\frac{2\eta}{B}f(w^{t}).
\tag{24}
\]

\subsection*{Step 6 – Telescoping Sum}
Take full expectation in (24) and sum from $t=0$ to $T-1$:
\[
\begin{aligned}
\frac{2\eta}{B}\sum_{t=0}^{T-1}\E\!\bigl[f(w^{t})\bigr]
\le &\; \norm{w^{0}-w^{*}}^{2}
+\frac{2\eta}{B}f(w^{0})
-\E\!\bigl[\norm{w^{T}-w^{*}}^{2}\bigr]
-\frac{2\eta}{B}\E\!\bigl[f(w^{T})\bigr]\\
\le &\; R^{2}+\frac{2\eta}{B}f(w^{0}),
\end{aligned}
\tag{25}
\]
where we dropped the non‑negative final two terms.  Since $f(w^{*})\le f(w^{0})$,
\[
\frac{1}{T}\sum_{t=0}^{T-1}\E\!\bigl[f(w^{t})-f(w^{*})\bigr]
\le \frac{B\,R^{2}}{2\eta\,T}.
\tag{26}
\]

\subsection*{Step 7 – From Average of Iterates to Average Iterate}
By Jensen’s inequality,
\[
f\!\left(\bar w_{T}\right)
\le \frac{1}{T}\sum_{t=0}^{T-1}f(w^{t}),
\qquad
\bar w_{T}:=\frac{1}{T}\sum_{t=0}^{T-1}w^{t}.
\tag{27}
\]
Taking expectation and using (26) gives
\[
\E\!\bigl[f(\bar w_{T})\bigr]-f(w^{*})
\le \frac{B\,R^{2}}{2\eta\,T}.
\tag{28}
\]

\subsection*{Step 8 – Insert the Stepsize}
Recall $\eta=1/(\bar L B)$.  Substituting into (28) yields
\[
\E\!\bigl[f(\bar w_{T})\bigr]-f(w^{*})
\le \frac{B^{2}\,\bar L\,R^{2}}{T},
\tag{29}
\]
which is exactly the bound claimed in \eqref{thm:main}.  Hence the theorem holds. \qed

\section*{Rate Derivation (With Constants)}
The final bound (29) can be written with an explicit constant $C$:
\[
\E\!\bigl[f(\bar w_{T})\bigr]-f(w^{*})\le
C\frac{1}{T},
\qquad C:=B^{2}\,\bar L\,R^{2}.
\]
If all blocks have identical Lipschitz constants $L_{b}=L$, then $\bar L=L$ and
$C=B^{2}LR^{2}$.

\section*{Special Cases}
\begin{enumerate}
\item \textbf{Full Gradient Descent.} $B=1$ reduces (4) to the classic
$\displaystyle\frac{L\,R^{2}}{T}$ bound.
\item \textbf{Coordinate Descent on Separable Quadratics.} For $f(w)=\frac12 w^{\top}Q w$ with $Q$ diagonal,
$L_{b}=Q_{bb}$ and the bound matches the exact convergence rate of the
Gauss–Seidel method.
\item \textbf{Strongly Convex Functions.} If $f$ is $\mu$‑strongly convex,
the same proof with the stronger inequality
$f(w^{t})-f(w^{*})\ge\frac{\mu}{2}\norm{w^{t}-w^{*}}^{2}$
leads to a linear recursion
$\E\!\bigl[\norm{w^{t+1}-w^{*}}^{2}\bigr]\le
\left(1-\frac{\mu}{\bar L B}\right)^{t}\E\!\bigl[\norm{w^{0}-w^{*}}^{2}\bigr]$,
hence exponential convergence.
\end{enumerate}

